```js
/**
 * Compute progressive tax on income using a bracket schedule.
 *
 * @param {number} incomeCents - non-negative integer, income in cents
 * @param {{ upTo: number | null, rateBp: number }[]} schedule - brackets, last one must have upTo: null
 * @returns {{ totalCents: number, perBracket: { upTo: number | null, rateBp: number, taxableCents: number, taxCents: number }[] }}
 */
export function computeTax(incomeCents, schedule) {
	validateSchedule(schedule);

	if (!Number.isInteger(incomeCents) || incomeCents < 0) {
		throw new RangeError("incomeCents must be a non-negative integer");
	}

	const perBracket = [];
	let totalCents = 0;
	let lowerBound = 0;

	for (const bracket of schedule) {
		const upperBound = bracket.upTo === null ? Number.POSITIVE_INFINITY : bracket.upTo;
		const taxableCents = Math.max(0, Math.min(incomeCents, upperBound) - lowerBound);
		const taxCents = roundBpToCents(taxableCents, bracket.rateBp);

		perBracket.push({
			upTo: bracket.upTo,
			rateBp: bracket.rateBp,
			taxableCents,
			taxCents,
		});

		totalCents += taxCents;
		lowerBound = upperBound;
	}

	return { totalCents, perBracket };
}

/**
 * @param {number} taxableCents
 * @param {number} rateBp
 * @returns {number} taxableCents * rateBp / 10000 rounded to nearest cent, ties to even
 */
function roundBpToCents(taxableCents, rateBp) {
	const num = BigInt(taxableCents) * BigInt(rateBp);
	const whole = num / 10000n;
	const rem = num % 10000n;
	if (rem > 5000n || (rem === 5000n && (whole & 1n) === 1n)) {
		return Number(whole + 1n);
	}
	return Number(whole);
}

function validateSchedule(schedule) {
	if (!Array.isArray(schedule) || schedule.length === 0) {
		throw new TypeError("schedule must be a non-empty array of brackets");
	}

	const lastIndex = schedule.length - 1;
	let previousUpTo = 0;

	for (let i = 0; i < schedule.length; i++) {
		const bracket = schedule[i];
		if (bracket === null || typeof bracket !== "object" || Array.isArray(bracket)) {
			throw new TypeError(`schedule[${i}] must be an object`);
		}

		const { upTo, rateBp } = bracket;
		const isLast = i === lastIndex;

		if (isLast) {
			if (upTo !== null) {
				throw new TypeError("the last bracket must have upTo: null");
			}
		} else if (!Number.isInteger(upTo) || upTo <= 0 || upTo <= previousUpTo) {
			throw new TypeError("upTo must be a positive integer, strictly increasing, with only the last bracket null");
		}

		if (!Number.isInteger(rateBp) || rateBp < 0 || rateBp > 10000) {
			throw new TypeError("rateBp must be an integer from 0 to 10000");
		}

		if (!isLast) {
			previousUpTo = upTo;
		}
	}
}
```

